"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/ecommerce/variants/01-product-grid";
export interface ArtemisEcommerceProductGridProps { className?: string;  }
export function ArtemisEcommerceProductGrid({ className }: ArtemisEcommerceProductGridProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { Listbox, ListboxButton, ListboxOption, ListboxOptions } from "../../../lib/headless";
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { products, type Product } from "./01-product-grid/data";
type Category = "All objects" | Product["category"];
type SortMode = "featured" | "price-low" | "price-high";
const categories = ["All objects", "Audio", "Everyday", "Workspace"] as const;

const sortOptions: {
    value: SortMode;
    label: string;
}[] = [
    { value: "featured", label: "Featured" },
    { value: "price-low", label: "Price: low to high" },
    { value: "price-high", label: "Price: high to low" },
];
function ProductCard({ product, added, onAdd, reducedMotion }: {
    product: Product;
    added: boolean;
    onAdd: () => void;
    reducedMotion: boolean;
}) {
    return <motion.article initial={reducedMotion ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={reducedMotion ? { duration: 0 } : { duration: 0.3, ease: ARTEMIS_EASE_OUT }}>
    <div className="art:relative art:aspect-[4/5] art:overflow-hidden art:rounded-3xl art:bg-muted">
      <motion.img src={product.image} alt={product.alt} loading="lazy" width="600" height="750" className="art:size-full art:object-cover" whileHover={reducedMotion ? undefined : { scale: 1.04 }} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT }}/>
      {product.badge && <span className="art:absolute art:left-3 art:top-3 art:rounded-full art:bg-background/95 art:px-3 art:py-1.5 art:text-xs art:font-medium">{product.badge}</span>}
    </div>
    <div className="art:mt-4 art:flex art:items-start art:justify-between art:gap-2"><div><p className="art:text-xs art:text-muted-foreground">{product.category}</p><h3 className="art:mt-1 art:text-xl art:font-medium">{product.name}</h3></div></div>
    <div className="art:mt-3 art:flex art:items-center art:justify-between art:gap-3">
      <span className="art:text-sm art:font-medium art:tabular-nums">{`$${product.price.toFixed(2)}`}</span>
      <motion.button type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:px-3 art:text-xs art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" tabIndex={0} whileHover={reducedMotion ? undefined : { scale: 1.01 }} whileTap={reducedMotion ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={onAdd}>
        {added ? <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-3.5" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg> : <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-plus art:size-3.5" aria-hidden="true"><path d="M5 12h14"/><path d="M12 5v14"/></svg>}
        {added ? "Add another" : "Add to bag"}
      </motion.button>
    </div>
  </motion.article>;
}
export default function EcommerceProductGrid() {
const artemisInstanceId = useArtemisInstanceId();
const tabs = categories.map((category, index) => ({ value: category, label: category, id: `${artemisInstanceId}-R_9bsnpfdb_-tab-${index}`, ariaControls: `${artemisInstanceId}-R_9bsnpfdb_-products` }));

    const [category, setCategory] = useState<Category>("All objects");
    const [sortMode, setSortMode] = useState<SortMode>("featured");
    const [bag, setBag] = useState<Record<string, number>>({});
    const [lastAdded, setLastAdded] = useState("");
    const reducedMotion = Boolean(useReducedMotion());
    const count = Object.values(bag).reduce((sum, value) => sum + value, 0);
    const visible = products.filter(product => category === "All objects" || product.category === category);
    if (sortMode === "price-low")
        visible.sort((a, b) => a.price - b.price);
    if (sortMode === "price-high")
        visible.sort((a, b) => b.price - a.price);
    const onAdd = (product: Product) => { setBag(previous => ({ ...previous, [product.id]: (previous[product.id] ?? 0) + 1 })); setLastAdded(`${product.name} added to the demo bag.`); };
    return <section className="art:w-full art:bg-background art:px-4 art:py-16 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-20">
    <div className="art:mx-auto art:max-w-6xl">
      <div className="art:flex art:items-start art:justify-between art:gap-6">
        <div className="art:max-w-xl"><p className="art:text-sm art:text-muted-foreground">The everyday collection</p><h2 className="art:mt-3 art:text-balance art:tracking-tight art:text-xl art:font-medium">Good things. Every day.</h2><p className="art:mt-4 art:text-sm art:leading-6 art:text-muted-foreground art:@min-[640px]/artemis:text-base">Considered objects for your desk, your downtime, and everything in between.</p></div>
        <span className="art:flex art:shrink-0 art:items-center art:gap-2 art:rounded-full art:bg-muted art:px-3 art:py-2 art:text-sm"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-shopping-bag art:size-4" aria-hidden="true"><path d="M16 10a4 4 0 0 1-8 0"/><path d="M3.103 6.034h17.794"/><path d="M3.4 5.467a2 2 0 0 0-.4 1.2V20a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6.667a2 2 0 0 0-.4-1.2l-2-2.667A2 2 0 0 0 17 2H7a2 2 0 0 0-1.6.8z"/></svg><span className="art:sr-only">Items added: </span>{count}</span>
      </div>
      <div className="art:mt-9 art:flex art:flex-wrap art:items-center art:justify-between art:gap-4">
        <div className="art:min-w-0 art:max-w-full"><ArtemisSegmentedTabs items={tabs} value={category} onValueChange={value => setCategory(value as Category)} listClassName="art:inline-flex art:items-center art:gap-1 art:rounded-full art:p-1 art:max-w-full art:overflow-x-auto art:bg-muted" buttonClassName="art:h-9 art:rounded-full art:text-sm art:focus-visible:ring-2 art:focus-visible:ring-ring" indicatorClassName="art:rounded-full" layout="position" ariaLabel="Product categories" roving/></div>
        <Listbox as="div" value={sortMode} onChange={setSortMode} className="art:relative art:inline-block art:text-left">
          <ListboxButton id={`headlessui-listbox-button-${artemisInstanceId}-R_ripbsnpfdb_`} aria-label="Sort products" className="art:inline-flex art:min-w-40 art:items-center art:justify-between art:gap-2 art:border art:border-border art:px-3 art:text-left art:font-medium art:text-foreground art:text-sm art:transition-colors art:hover:border-border-strong art:disabled:pointer-events-none art:disabled:opacity-50 art:outline-none art:ring-0 art:focus:outline-none art:focus:ring-0 art:focus-visible:outline-none art:data-focus:outline-none art:data-focus:ring-0 art:data-open:ring-0 art:h-10 art:rounded-full art:bg-background art:focus-visible:ring-2 art:focus-visible:ring-ring">
            {({ open }) => <><span className="art:min-w-0 art:truncate">{sortOptions.find(option => option.value === sortMode)?.label}</span><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-chevron-down art:size-4 art:shrink-0 art:text-muted-foreground art:transition-transform${open ? " art:rotate-180" : ""}`} aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></>}
          </ListboxButton>
          <ListboxOptions id={`headlessui-listbox-options-${artemisInstanceId}-R_1bipbsnpfdb_`} anchor={{ to: "bottom end", gap: 8, padding: 12 }} transition className="art:z-[120] art:overflow-hidden art:rounded-2xl art:border art:border-border-strong/50 art:bg-background art:p-1.5 art:backdrop-blur-xl art:outline-none art:ring-0 art:focus:outline-none art:focus:ring-0 art:focus-visible:outline-none art:focus-visible:ring-0 art:data-focus:outline-none art:data-focus:ring-0 art:transition art:duration-150 art:ease-out art:data-closed:scale-95 art:data-closed:opacity-0 art:origin-top art:w-64 art:shadow-none art:max-w-[calc(100vw-1.5rem)]">
            {sortOptions.map(option => <ListboxOption key={option.value} value={option.value} className="art:group art:flex art:min-h-11 art:cursor-pointer art:items-center art:gap-3 art:rounded-xl art:px-3 art:py-2 art:text-left art:transition-colors art:data-focus:bg-primary/5 art:data-disabled:pointer-events-none art:data-disabled:opacity-50"><span className="art:min-w-0 art:flex-1"><span className="art:block art:truncate art:text-sm">{option.label}</span></span><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-4 art:shrink-0 art:opacity-0 art:group-data-selected:opacity-100" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg></ListboxOption>)}
          </ListboxOptions>
        </Listbox>
      </div>
      <div role="tabpanel" id={`${artemisInstanceId}-R_9bsnpfdb_-products`} aria-labelledby={`${artemisInstanceId}-R_9bsnpfdb_-tab-${categories.indexOf(category)}`} className="art:mt-6 art:grid art:gap-x-5 art:gap-y-8 art:@min-[640px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:grid-cols-4">
        {visible.map(product => <ProductCard key={product.id} product={product} added={Boolean(bag[product.id])} onAdd={() => onAdd(product)} reducedMotion={reducedMotion}/>)}
      </div>
      <output className="art:mt-5 art:block art:min-h-5 art:text-sm art:text-muted-foreground">{lastAdded}</output>
    </div>
  </section>;
}

// @zeus-internal
export type Product = {
    id: string;
    category: "Audio" | "Everyday" | "Workspace";
    name: string;
    price: number;
    image: string;
    alt: string;
    badge?: string;
};
export const products: Product[] = [
    { id: "headphones", category: "Audio", name: "Studio headphones", price: 129, image: "/assets/artemis/edca6a91e5cbdf9f7f6d.avif", alt: "Over-ear headphones against a warm yellow background", badge: "Bestseller" },
    { id: "watch", category: "Everyday", name: "Everyday watch", price: 89, image: "/assets/artemis/52d510674e9e2f9463ad.avif", alt: "Minimal wristwatch on a pale background" },
    { id: "camera", category: "Everyday", name: "Weekend camera", price: 349, image: "/assets/artemis/6060a1ab4061cea84083.avif", alt: "Camera and lens photographed up close", badge: "Just arrived" },
    { id: "lamp", category: "Workspace", name: "Focus desk lamp", price: 79, image: "/assets/artemis/0dbc3c5e66370608935f.avif", alt: "A desk lamp lighting a workspace" },
];
